// ─── HELPERS ───────────────────────────────────────────────────────────────────

const SUBJECTS = [
  { title: "Anatomy", description: "Test your knowledge of human anatomy", questions: anatomyQuestions },
  { title: "Physiology", description: "Test your knowledge of human physiology", questions: physiologyQuestions },
  { title: "Biochemistry", description: "Test your knowledge of biochemistry and metabolism", questions: biochemistryQuestions },
  { title: "Obstetrics and Gynaecology", description: "Test your knowledge of OB/GYN", questions: obgynQuestions },
  { title: "Paediatrics", description: "Test your knowledge of paediatric medicine", questions: paediatricQuestions },
  { title: "Community Medicine", description: "Test your knowledge of community and preventive medicine", questions: communityMedicineQuestions },
  { title: "Medicine and Surgery", description: "Test your knowledge of clinical medicine and surgery", questions: medicineAndSurgeryQuestions },
  { title: "Psychiatry", description: "Test your knowledge of psychiatry and mental health", questions: psychiatryQuestions },
];

async function seedQuizzes() {
  console.log('Starting quiz seeding...');
  console.log(`Seeding ${SUBJECTS.length} subjects with 50 questions each.\n`);

  for (const subject of SUBJECTS) {
    console.log(`\n--- Processing: ${subject.title} ---`);

    // 1. Create the quiz
    const { data: quiz, error: quizErr } = await supabase
      .from('quizzes')
      .insert({
        title: subject.title,
        description: subject.description,
        total_questions: subject.questions.length,
        duration_minutes: 60,
        pass_score: 60,
        is_published: true,
      })
      .select()
      .single();

    if (quizErr) {
      console.error(`  ERROR creating quiz "${subject.title}":`, quizErr.message);
      continue;
    }

    console.log(`  Created quiz: ${quiz.id}`);

    // 2. Insert all questions
    const questionsPayload = subject.questions.map((q, idx) => ({
      quiz_id: quiz.id,
      question_text: q.q,
      question_type: 'multiple_choice',
      points: 1,
      order_index: idx,
      explanation: q.exp,
    }));

    const { data: insertedQuestions, error: qErr } = await supabase
      .from('quiz_questions')
      .insert(questionsPayload)
      .select();

    if (qErr) {
      console.error(`  ERROR inserting questions for "${subject.title}":`, qErr.message);
      continue;
    }

    console.log(`  Inserted ${insertedQuestions.length} questions`);

    // 3. Insert answers for each question
    const answersPayload = [];
    for (let i = 0; i < subject.questions.length; i++) {
      const q = subject.questions[i];
      const questionId = insertedQuestions[i]?.id;
      if (!questionId) continue;

      for (let j = 0; j < q.opts.length; j++) {
        answersPayload.push({
          question_id: questionId,
          answer_text: q.opts[j],
          is_correct: q.opts[j] === q.ans,
          order_index: j,
        });
      }
    }

    const { error: aErr } = await supabase.from('quiz_answers').insert(answersPayload);

    if (aErr) {
      console.error(`  ERROR inserting answers for "${subject.title}":`, aErr.message);
      continue;
    }

    console.log(`  Inserted ${answersPayload.length} answer options`);
    console.log(`  Done: ${subject.title}`);
  }

  console.log('\n\nSeeding complete!');
}

seedQuizzes().catch(console.error);
